    }

    GuestIdentity identity = readGuestIdentity(body);
    Guest guest = new Guest(body.guestName(), body.guestEmail(), identity);
    return new NewReservation(
            body.roomNumber(), guest, body.checkIn(), body.checkOut(), body.guests(), body.ratePlan());
}

private static GuestIdentity readGuestIdentity(CreateReservationRequest body) {
    boolean hasCpf = !isBlank(body.guestCpf());
    boolean hasCnpj = !isBlank(body.companyCnpj()) && !isBlank(body.companyName());
    boolean hasPassport = !isBlank(body.guestPassport()) && !isBlank(body.guestCountry());

    int identityCount = (hasCpf ? 1 : 0) + (hasCnpj ? 1 : 0) + (hasPassport ? 1 : 0);
    if (identityCount != 1) {
        throw new HotelException(ErrorCode.INVALID_REQUEST,
                "the reservation must have exactly one identity: guestCpf, or companyCnpj+companyName, or guestPassport+guestCountry");
    }

    if (hasCpf) {
        return new IndividualIdentity(body.guestCpf());
    } else if (hasCnpj) {
        return new CorporateIdentity(body.companyCnpj(), body.companyName());
    } else {
        return new ForeignIdentity(body.guestPassport(), body.guestCountry());
    }
}

