    int identityCount = (hasCpf ? 1 : 0) + (hasCnpj ? 1 : 0) + (hasPassport ? 1 : 0);
    if (identityCount != 1) {
        throw new HotelException(ErrorCode.INVALID_REQUEST,
                "the reservation must have exactly one identity: guestCpf, or companyCnpj+companyName, or guestPassport+guestCountry");
    }

